# shellcheck shell=bash
# GTK 4 / libadwaita stylesheet (dark): named colors, the accent variables
# libadwaita 1.6+ reads, and the grey-accent override in file views.
# Output: ports/gtk/gtk.css

build_gtk() {
    jq -r '
        .variants.dark as $c
        | def dc($k; $v): "@define-color \($k) \($v);";
        "/* Terminal Noir for GTK 4 / libadwaita (dark). https://terminalnoir.web.app",
        " * Generated by scripts/build from palette/palette.json. */",
        "",
        dc("accent_color"; $c.accent.primary),
        dc("accent_bg_color"; $c.accent.primary),
        dc("accent_fg_color"; $c.accent.onPrimary),
        dc("destructive_bg_color"; $c.accent.error),
        dc("destructive_fg_color"; $c.accent.onPrimary),
        dc("success_bg_color"; $c.accent.success),
        dc("success_fg_color"; $c.accent.onPrimary),
        dc("warning_bg_color"; $c.accent.warning),
        dc("warning_fg_color"; $c.accent.onPrimary),
        dc("error_bg_color"; $c.accent.error),
        dc("error_fg_color"; $c.accent.onPrimary),
        dc("window_bg_color"; $c.surface.base),
        dc("window_fg_color"; $c.text.primary),
        dc("view_bg_color"; $c.surface.base),
        dc("view_fg_color"; $c.text.primary),
        dc("headerbar_bg_color"; $c.surface.base),
        dc("headerbar_fg_color"; $c.text.primary),
        dc("headerbar_backdrop_color"; $c.surface.base),
        dc("sidebar_bg_color"; $c.surface.elevated),
        dc("sidebar_fg_color"; $c.text.primary),
        dc("card_bg_color"; $c.surface.elevated),
        dc("card_fg_color"; $c.text.primary),
        dc("popover_bg_color"; $c.surface.elevated),
        dc("popover_fg_color"; $c.text.primary),
        dc("dialog_bg_color"; $c.surface.base),
        dc("dialog_fg_color"; $c.text.primary),
        "",
        "/* libadwaita 1.6+ derives the accent from the system accent-color preset",
        " * through these variables. */",
        ":root {",
        "  --accent-bg-color: \($c.accent.primary);",
        "  --accent-color: \($c.accent.primary);",
        "  --accent-fg-color: \($c.accent.onPrimary);",
        "}",
        "",
        "/* Nautilus and the libadwaita file chooser force a grey accent in file",
        " * views. The user stylesheet loads above both, so the same selectors win. */",
        ".nautilus-list-view listview,",
        ".nautilus-grid-view gridview,",
        ".nautilus-network-view listview {",
        "  --accent-bg-color: \($c.accent.primary);",
        "  --accent-color: \($c.accent.primary);",
        "}",
        "",
        "filechooser columnview > listview,",
        "filechooser gridview,",
        "filechooser placesview > stack > scrolledwindow list {",
        "  --accent-bg-color: \($c.accent.primary);",
        "  --accent-color: \($c.accent.primary);",
        "}"
    ' "$PALETTE" > "$OUT/ports/gtk/gtk.css"
}
